        mipc_sim_pin_desc_struct(struct_tree, tlv[t][0])
    elseif tlv[4+33024] ~= nill then
        tree:add(mipc_sensitive, tlv[4+33024][0],"SP_PIN: <user data>")
    end
    if tlv[5+256] ~= nill then
        local t = 256 + 5
        -- struct sim_pin_desc
