function mipc_call_approve_incoming_cmd(tvb, root, offset_start, msg_offset, msg_len)
    local tree = root:add("TLV")
    local offset = offset_start
    local tlv = {}
    while offset < offset_start + msg_len do
        t = tvb:range(offset,2):le_uint()
        offset = offset + 2
        local l = tvb:range(offset,2):le_uint()
        offset = offset + 2
        if t == 0 then
            tree:add_le(tlv_result, tvb:range(offset,4))
            offset = offset + 4
        else
            if l == 0 then
                -- tlv array --
                tlv[t] = {[0] = tvb:range(offset+8, 2):le_uint(), [1] = tvb:range(offset+10, 2):le_uint(), [3] = tvb:range(offset+8, 4)}
                offset = offset + 12
            else
                tlv[t] = {[0] = tvb:range(offset,l), [1] = l}
                -- alignment t(2)+l(2)+v(?) = 8n --
                if (l+4)%8 ~= 0 then
                    l = l + 8 - ((l+4)%8)
                end
                offset = offset + l
            end
        end
    end
    if tlv[0+256] ~= nill then
        local t = 256 + 0
        tree:add_le(mipc_call_approve_incoming_cmd_t_callid, tlv[t][0]) 
    elseif tlv[0+33024] ~= nill then
        tree:add(mipc_sensitive, tlv[0+33024][0],"CALLID: <user data>")
    end
    if tlv[1+256] ~= nill then
        local t = 256 + 1
        local mipc_string = bytestostring(tlv[t][0], tlv[t][1])
        tree:add(mipc_call_approve_incoming_cmd_t_number, tlv[t][0], mipc_string) 
    elseif tlv[1+33024] ~= nill then
        tree:add(mipc_sensitive, tlv[1+33024][0],"NUMBER: <user data>")
    end
    if tlv[2+256] ~= nill then
        local t = 256 + 2
        tree:add_le(mipc_call_approve_incoming_cmd_t_toa, tlv[t][0]) 
    elseif tlv[2+33024] ~= nill then
        tree:add(mipc_sensitive, tlv[2+33024][0],"TOA: <user data>")
    end
    if tlv[3+256] ~= nill then
        local t = 256 + 3
        tree:add_le(mipc_call_approve_incoming_cmd_t_seq_no, tlv[t][0]) 
    elseif tlv[3+33024] ~= nill then
        tree:add(mipc_sensitive, tlv[3+33024][0],"SEQ_NO: <user data>")
    end
    if tlv[4+256] ~= nill then
        local t = 256 + 4
        tree:add_le(mipc_call_approve_incoming_cmd_t_mode, tlv[t][0]) 
    elseif tlv[4+33024] ~= nill then
        tree:add(mipc_sensitive, tlv[4+33024][0],"MODE: <user data>")
    end
end

